exercises.solution:
fn first_column(header: &mut String) -> &str {
    header.truncate(header.find(',').unwrap_or(header.len()));
    let start = header.len() - header.trim_start().len();
    header.drain(..start);
    header.truncate(header.trim_end().len());
    header.as_str()
}

fn main() {
    let mut header = String::from(" name,age ");
    assert_eq!(first_column(&mut header), "name");
}
